package cl.robermotos.delivery.service;
import cl.robermotos.delivery.model.DeliveryStatus; import org.springframework.stereotype.Service; import java.util.*; import java.util.concurrent.*;
@Service public class TrackingService { private final Map<String,DeliveryStatus> states=new ConcurrentHashMap<>(); public void start(String id){states.put(id,DeliveryStatus.BUSCANDO_REPARTIDOR); CompletableFuture.runAsync(()->{DeliveryStatus[] seq={DeliveryStatus.REPARTIDOR_ASIGNADO,DeliveryStatus.RETIRADO,DeliveryStatus.EN_CAMINO,DeliveryStatus.ENTREGADO}; for(var s:seq){try{Thread.sleep(5000);}catch(InterruptedException e){Thread.currentThread().interrupt();return;} states.put(id,s);}});} public void update(String id,DeliveryStatus s){states.put(id,s);} public DeliveryStatus get(String id){return states.getOrDefault(id,DeliveryStatus.BUSCANDO_REPARTIDOR);} }